var DASH_LOG_SHEET = '\u30ED\u30B0';
var DASH_STALE_MINUTES = 15;

function dashMainValues_() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sh = ss.getSheets()[0];
  var last = sh.getLastRow();
  if (last < 2) return [];
  return sh.getRange(2, 1, last - 1, 13).getDisplayValues();
}

function dashLogValues_() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sh = ss.getSheetByName(DASH_LOG_SHEET);
  if (!sh || sh.getLastRow() < 2) return [];
  return sh.getRange(2, 1, sh.getLastRow() - 1, 5).getDisplayValues();
}

function dashParseDate_(value) {
  if (value instanceof Date) return value;
  var s = String(value || '').trim();
  if (!s) return null;
  var m = s.match(/(\\d{4})\\D(\\d{1,2})\\D(\\d{1,2})\\D*\\s*(\\d{1,2}):(\\d{2})/);
  if (!m) return null;
  return new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5]);
}

function dashClassify_(row) {
  var onOff = String(row[6] || '').toUpperCase();
  if (onOff === 'OFF') return 'off';
  var lastCheck = dashParseDate_(row[4]);
  if (!lastCheck) return 'error';
  if (new Date().getTime() - lastCheck.getTime() > DASH_STALE_MINUTES * 60000) return 'stale';
  var operation = String(row[1] || row[2] || '');
  if (!operation || operation.indexOf('\u904B\u884C\u306A\u3057') !== -1) return 'idle';
  return 'running';
}

function getVehicleStatusList() {
  return dashMainValues_().map(function (row, i) {
    return {
      row: i + 2,
      name: row[3],
      operation: row[1] || row[2],
      lastCheck: row[4],
      lastRun: row[5],
      onOff: row[6],
      stop: row[9],
      via: row[10],
      nextTime: row[11],
      nextOperation: row[12],
      state: dashClassify_(row)
    };
  }).filter(function (v) { return v.name || v.operation; });
}

function getDashboardData() {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getSheets()[0];
  var vehicles = getVehicleStatusList();
  var logs = getVehicleCalendarData('', '');
  return {
    updatedAt: sheet.getRange(1, 8).getDisplayValue(),
    fetchedAt: new Date().toISOString(),
    vehicles: vehicles,
    logCount: logs.count || 0
  };
}

